(7588315, 1222982, 96751, '<td valign="top">Good choice to flip the image. Could have been straighter, and avoided that blank sky on the right.</td>', 'Good choice to flip the image. Could have been straighter, and avoided that blank sky on the right.', '2018-08-01 22:41:22.000000', NULL, 1),
